package cabinet

const recoveryTemplates = `
{{define "recovery-admin"}}{{template "head"}}<body><header><a class="brand" href="/">Среда</a><span>Администратор</span></header><main><h1>Восстановление пароля пользователя</h1><p>Выберите обычного пользователя. Ссылка действует 1 час; выдача следующей немедленно отменяет предыдущую. После смены пароля все существующие сессии пользователя отзываются. Права и состояние ресурсов сохраняются.</p>{{if .Link}}<section class="card"><h2>Передайте ссылку лично</h2><p><a href="{{.Link}}">{{.Link}}</a></p><p>Действует до {{.Expires}}. Сохраните сейчас: ссылка показывается один раз. Почта не отправляется.</p></section>{{end}}<section class="card"><form method="post" action="/admin/password-recovery"><input type="hidden" name="csrf" value="{{.CSRF}}"><label for="user_id">Пользователь</label><select id="user_id" name="user_id" required>{{range .Users}}<option value="{{.ID}}">{{.Login}}</option>{{end}}</select><button type="submit">Создать ссылку восстановления</button></form><p>Аварийный доступ администратора восстанавливает оператор вручную на маме.</p></section></main></body></html>{{end}}
{{define "recovery"}}{{template "head"}}<body><header><span class="brand">Среда</span></header><main><section class="card"><h1>Новый пароль</h1><p>Действует до {{.Expires}}. Задайте пароль самостоятельно: администратор его не получает. Все прежние сеансы будут завершены; затем войдите с новым паролем.</p>{{if .Error}}<p class="error" role="alert">{{.Error}}</p>{{end}}<form method="post" action="/recover/{{.Token}}"><input type="hidden" name="csrf" value="{{.CSRF}}"><label for="password">Новый пароль (12–72 байта)</label><input id="password" name="password" type="password" minlength="12" autocomplete="new-password" required><button class="submit" type="submit">Сохранить пароль</button></form></section></main></body></html>{{end}}
`
